// Pins sporesAnalysis to the figures of Lombardi et al. (2020) and to the validated VM
// ensembles (docs/issues-drafts/19-plan-spores-paper-validation.md). Fixtures are
// regenerated by fixtures/spores/extract.mjs; capacities in kW, as the VM runs wrote them.
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { sporeMetrics, bestRanking } from '../sporesAnalysis.js';
import { METRICS } from '../scenarioStudio/presets/lombardi2020Italy.js';

const load = (name) => JSON.parse(readFileSync(new URL(`./fixtures/spores/${name}.json`, import.meta.url), 'utf8'));
const pct = (x) => Math.round(1000 * x) / 10;
const GW = 1e6; // kW

function rank(slack, metrics = METRICS) {
  const { meta, spores } = load(`ensemble_${slack}`);
  const rows = spores.map(s => sporeMetrics(s, meta, metrics, spores[0]));
  return { rows, ranking: bestRanking(rows) };
}

describe('hourly cost optimum (paper: 26.1 % minimum line CF on SICI–SUD)', () => {
  it('reproduces the minimum inter-zonal capacity factor', () => {
    const { hours, spore } = load('hourly_optimum_lines');
    const m = sporeMetrics(spore, { hours }, METRICS);
    expect(pct(m.minLineCF)).toBe(26.1);
    expect(Object.entries(m.lineCF).sort((a, b) => a[1] - b[1])[0][0]).toBe('sici–sud');
  });
});

// Wind share 19.5 % (paper, hourly optimum) can't be pinned: the hourly folder holds no capacities.
// The 3H optimum (spore 0 of every ensemble) gives 20.3 % in SARD, min CF 23.6 %.
const EXPECTED = {
  5: { subset: 34, lowWind: 12.8, highCF: 36.2, overcap: 10.6 },
  10: { subset: 46, lowWind: 10.1, highCF: 47.2, overcap: 43.1 },
  20: { subset: 49, lowWind: 11.5, highCF: 60.6, overcap: 52.0 },
};

describe.each([5, 10, 20])('final ensemble at %i % slack', (slack) => {
  const { rows, ranking } = rank(slack);
  const e = EXPECTED[slack];

  it('3H cost optimum: wind share and minimum CF', () => {
    expect(pct(rows[0].maxWindShare)).toBe(20.3);
    expect(rows[0].maxWindRegion).toBe('sard');
    expect(pct(rows[0].minLineCF)).toBe(23.6);
  });

  it('Table S1 subset size and Table 1 best SPOREs', () => {
    expect(ranking.subset.length).toBe(e.subset);
    expect(pct(ranking.lowWindConcentration.maxWindShare)).toBe(e.lowWind);
    expect(pct(ranking.highTransmissionUse.minLineCF)).toBe(e.highCF);
    expect(Math.round(ranking.highOvercapacity.overcapacity / GW * 10) / 10).toBe(e.overcap);
  });
});

describe('the rules the figures depend on', () => {
  it('dropping offshore wind from windTechs changes the wind share', () => {
    const { rows } = rank(5, { ...METRICS, windTechs: ['wind', 'wind_new'] });
    expect(pct(rows[0].maxWindShare)).not.toBe(20.3);
  });
  it('a stricter CF cutoff shrinks the subset', () => {
    const { rows } = rank(5);
    expect(bestRanking(rows, { minCF: 0.35 }).subset.length).toBeLessThan(34);
  });
});
